package com.huy.enterprise.alert; import com.huy.enterprise.common.enums.*; import jakarta.validation.constraints.*; import java.time.OffsetDateTime; import java.util.UUID; record AlertRequest(@NotBlank String title,@NotBlank String message,@NotBlank String alertType,AlertPriority priority,UUID recipientUserId,UUID riskEventId){} record AlertStatusRequest(@NotNull AlertStatus status){} record AlertResponse(UUID id,String title,String message,String alertType,AlertPriority priority,AlertStatus status,UUID recipientUserId,UUID riskEventId,OffsetDateTime resolvedAt){static AlertResponse from(Alert a){return new AlertResponse(a.getId(),a.getTitle(),a.getMessage(),a.getAlertType(),a.getPriority(),a.getStatus(),a.getRecipientUser()==null?null:a.getRecipientUser().getId(),a.getRiskEvent()==null?null:a.getRiskEvent().getId(),a.getResolvedAt());}}
